/**
 * The set of well-known event types emitted by an {@link AgentSession}.
 *
 * The union is intentionally open ({@link AgentEventType} | `string`) so that
 * consumers may emit custom event kinds without having to widen this type.
 */
export type AgentEventType =
  | 'stream_start'
  | 'stream_end'
  | 'message'
  | 'session_update'
  | 'elicitation_response';

/**
 * A single event yielded by an agent stream.
 *
 * Every event is tagged with a stable {@link AgentEvent.id | id} and the
 * {@link AgentEvent.streamId | streamId} of the stream it belongs to. Event
 * kinds carry additional, kind-specific fields (for example `role` on a
 * `message` event or `reason` on a `stream_end` event); these are modelled via
 * the index signature so that implementations remain flexible.
 */
export interface AgentEvent {
  /** The kind of event, e.g. `stream_start`, `message`, `stream_end`. */
  type: AgentEventType | string;
  /** A unique identifier for this event within the session. */
  id: string;
  /** The identifier of the stream this event belongs to. */
  streamId: string;
  /** The author of a `message` event. */
  role?: 'user' | 'assistant' | string;
  /** The payload of a `message` event. */
  content?: unknown;
  /** The reason a `stream_end` event was emitted (e.g. `completed`, `aborted`). */
  reason?: string;
  /** Kind-specific fields. */
  [key: string]: unknown;
}

/**
 * A partial {@link AgentEvent} used when queueing responses.
 *
 * Only {@link AgentEvent.type | type} is required; the session fills in the
 * {@link AgentEvent.id | id} and {@link AgentEvent.streamId | streamId} when the
 * event is materialised.
 */
export type MockAgentEvent = Partial<AgentEvent> & Pick<AgentEvent, 'type'>;

/** Options controlling how a queued response behaves. */
export interface PushResponseOptions {
  /**
   * When `true`, the stream is left open after the queued events are emitted
   * (no automatic `stream_end` is appended), allowing further events to be
   * pushed via {@link AgentSession} implementations.
   */
  keepOpen?: boolean;
}

/** Options for {@link AgentSession.stream}. */
export interface StreamOptions {
  /** Stream to consume. Defaults to the most recently created stream. */
  streamId?: string;
  /** Resume streaming after the event with this id. */
  eventId?: string;
}

/** The discriminator for {@link AgentSend} payloads. */
export type AgentSendType = 'message' | 'update' | 'elicitations' | 'action';

/**
 * A payload sent to an {@link AgentSession} via {@link AgentSession.send}.
 */
export interface AgentSend {
  /** The kind of payload being sent. */
  type: AgentSendType;
  /** For `message` sends: the author of the message. */
  role?: string;
  /** For `message` sends: the message payload. */
  content?: unknown;
  /** For `message` sends: an alternate message payload. */
  message?: unknown;
  /** For `update` sends: the session properties to change. */
  update?: Record<string, unknown>;
  /** For `elicitations` sends: the elicitation responses to emit. */
  elicitations?: unknown[];
  /** For `action` sends: the action being requested. */
  action?: unknown;
  /** Additional, kind-specific fields. */
  [key: string]: unknown;
}

/**
 * An agent session capable of accepting input, streaming events, and being
 * aborted.
 */
export interface AgentSession {
  /** The complete, ordered history of events across all streams. */
  readonly events: AgentEvent[];
  /** Send a payload to the agent, returning the id of the resulting stream. */
  send(payload: AgentSend): Promise<{ streamId: string }>;
  /** Stream events from the latest (or a specified) stream. */
  stream(options?: StreamOptions): AsyncIterableIterator<AgentEvent>;
  /** Abort any in-flight streams. */
  abort(): Promise<void>;
