  StreamOptions,
} from './types.js';

/** A response queued via {@link MockAgentSession.pushResponse}. */
interface QueuedResponse {
  events: MockAgentEvent[];
  options?: PushResponseOptions;
}

/** Internal bookkeeping for a single stream. */
interface StreamState {
  id: string;
  events: AgentEvent[];
  /** Whether a `stream_end` event has been emitted for this stream. */
  closed: boolean;
  /** Resolvers for consumers suspended waiting for more events. */
  waiters: Array<() => void>;
}

/**
 * An in-memory {@link AgentSession} implementation for tests.
 *
 * `MockAgentSession` lets a test queue the events a fake agent should emit,
 * drive them through the same `send` / `stream` / `abort` surface as a real
 * session, and inspect the complete {@link MockAgentSession.events | event
