  private readonly streamOrder: string[] = [];
  private readonly responseQueue: QueuedResponse[] = [];
  private sessionState: Record<string, unknown> = {};
  private eventSeq = 0;
  private streamSeq = 0;

  constructor(initialEvents?: AgentEvent[]) {
    if (initialEvents) {
      for (const event of initialEvents) {
        this.recordInitialEvent(event);
      }
    }
  }

  /** The complete, ordered history of events across every stream. */
  get events(): AgentEvent[] {
    return [...this.history];
  }

  /** The current session state accumulated from `update` sends. */
  get state(): Record<string, unknown> {
    return { ...this.sessionState };
  }

  /**
   * Queue a set of partial events to be emitted on the next {@link send} call.
   * Multiple responses may be queued; each `send` consumes the oldest one.
   */
  pushResponse(events: MockAgentEvent[], options?: PushResponseOptions): void {
    this.responseQueue.push({ events, options });
  }

  /**
   * Send a payload to the mock agent.
   *
   * A `stream_start` event is prepended when absent and a `stream_end` event is
   * appended unless the queued response opted to keep the stream open (or an
   * explicit `stream_end` was already provided). Payload-specific events are
   * injected before the queued response events.
   */
  async send(payload: AgentSend): Promise<{ streamId: string }> {
