    // Build the payload-derived events first so that unsupported payloads
    // throw before a stream is registered.
    const injected = this.buildInjectedEvents(payload);

    const queued = this.responseQueue.shift();
    const responseEvents = queued?.events ?? [];
    const keepOpen = queued?.options?.keepOpen ?? false;

    const partials: MockAgentEvent[] = [...injected, ...responseEvents];

    if (!partials.some((event) => event.type === 'stream_start')) {
      partials.unshift({ type: 'stream_start' });
